<?php

defined('ABSPATH')||exit;
final class GCU_Admin{
public function hooks(){add_action('admin_menu',array($this,'menu'));add_action('admin_post_gcu_repair',array($this,'repair'));add_action('admin_post_gcu_rollback',array($this,'rollback'));add_action('admin_post_gcu_toggle',array($this,'toggle'));add_action('admin_notices',array($this,'migration_notice'));}
public function menu(){add_options_page(__('Global Clinic USP Governance','global-clinic-usp-integration'),__('Global Clinic USP','global-clinic-usp-integration'),GCU_Capabilities::SYSTEM_CHECK,'global-clinic-usp-integration',array($this,'page'));}
public function page(){if(!GCU_Capabilities::can(GCU_Capabilities::SYSTEM_CHECK,null,'admin_page')){wp_die(esc_html__('You are not authorized to view this page.','global-clinic-usp-integration'));}$r=GCU_Plugin::instance()->observability()->health_report();$notice=isset($_GET['gcu_notice'])?sanitize_key(wp_unslash($_GET['gcu_notice'])):'';?><div class="wrap"><h1><?php esc_html_e('Global Clinic USP Governance','global-clinic-usp-integration');?></h1><p><?php esc_html_e('File 14 owns approved value-proposition content, placement governance, claim evidence, ethical conversion measurement and destination contracts. It does not own doctor, clinic, appointment, payment or clinical truth.','global-clinic-usp-integration');?></p><?php if($notice):?><div class="notice notice-info inline"><p><?php echo esc_html(str_replace('-',' ',$notice));?></p></div><?php endif;?><h2><?php esc_html_e('Release and System Check','global-clinic-usp-integration');?></h2><table class="widefat striped"><tbody><tr><th>Plugin</th><td><?php echo esc_html($r['version']);?></td></tr><tr><th>Schema</th><td><?php echo esc_html($r['schema_version'].' / '.$r['expected_schema']);?></td></tr><tr><th>State</th><td><?php echo esc_html($r['enabled']?'enabled':'safe-mode disabled');?></td></tr><tr><th>Future schema</th><td><?php echo esc_html($r['future']['schema_version'].' / '.$r['future']['expected_schema'].' / '.($r['future']['schema_verified']?'verified':'unverified').($r['future']['safe_mode']?' / safe mode':''));?></td></tr><tr><th>Dependencies</th><td><?php echo esc_html(wp_json_encode($r['dependencies']));?></td></tr><tr><th>Cron</th><td><?php echo esc_html(wp_json_encode($r['cron']));?></td></tr><tr><th>Routes</th><td><?php echo esc_html(wp_json_encode($r['routes']));?></td></tr><tr><th>Missing tables</th><td><?php echo esc_html($r['missing_tables']?implode(', ',$r['missing_tables']):'none');?></td></tr><tr><th>Non-InnoDB</th><td><?php echo esc_html($r['non_innodb_tables']?wp_json_encode($r['non_innodb_tables']):'none');?></td></tr><tr><th>Audit chain</th><td><?php echo esc_html(($r['audit_chain']['valid']?'valid':'invalid').' / '.$r['audit_chain']['scope'].' / '.$r['audit_chain']['checked'].' of '.$r['audit_chain']['total']);?></td></tr><tr><th>Localization</th><td><?php echo esc_html($r['localization_complete']?'complete':'incomplete');?></td></tr><tr><th>Stale claims</th><td><?php echo esc_html($r['stale_claims']);?></td></tr></tbody></table><h2><?php esc_html_e('Destination Contracts','global-clinic-usp-integration');?></h2><table class="widefat striped"><thead><tr><th>Destination</th><th>Owner</th><th>State</th><th>URL</th></tr></thead><tbody><?php foreach($r['destinations']as$key=>$d):?><tr><td><?php echo esc_html($key);?></td><td><?php echo esc_html($d['owner']);?></td><td><?php echo esc_html($d['reason']);?></td><td><?php echo $d['url']?'<a href="'.esc_url($d['url']).'" target="_blank" rel="noopener noreferrer">Open</a>':'Unavailable';?></td></tr><?php endforeach;?></tbody></table><h2><?php esc_html_e('Safe Operations','global-clinic-usp-integration');?></h2><?php $this->action_form('gcu_repair',__('Run owner-scoped safe repair','global-clinic-usp-integration'));$this->action_form('gcu_rollback',__('Restore verified owner snapshot','global-clinic-usp-integration'));$this->action_form('gcu_toggle',$r['enabled']?__('Enter safe mode','global-clinic-usp-integration'):__('Leave safe mode','global-clinic-usp-integration'),array('enabled'=>$r['enabled']?'0':'1'));?><h2><?php esc_html_e('Canonical API Contracts','global-clinic-usp-integration');?></h2><p><code>GET /wp-json/gcu/v1/blocks</code> · <code>POST /wp-json/gcu/v1/event-token</code> · <code>POST /wp-json/gcu/v1/events</code> · <code>POST /wp-json/gcu/v1/content</code> · <code>PATCH /wp-json/gcu/v1/workflow/{machine}/{id}</code></p></div><?php }
public function repair(){$this->authorize('gcu_repair',GCU_Capabilities::SYSTEM_CHECK);$x=GCU_Install::safe_repair();if(is_wp_error($x)){wp_die(esc_html($x->get_error_message()));}$audit=GCU_Plugin::instance()->repository()->audit('safe_repair','module','file14','operations','Owner-scoped repair requested',array(),array('schema'=>GCU_SCHEMA_VERSION,'future_schema'=>GCU_FUTURE_SCHEMA_VERSION));if(false===$audit){wp_die(esc_html__('Repair completed but its mandatory audit record failed; File 14 remains contained in safe mode.','global-clinic-usp-integration'));}$this->redirect('safe-repair-completed');}
public function rollback(){$this->authorize('gcu_rollback',GCU_Capabilities::SYSTEM_CHECK);$x=GCU_Install::rollback_snapshot();if(!is_wp_error($x)){$audit=GCU_Plugin::instance()->repository()->audit('rollback_restored','module','file14','operations','Verified owner snapshot restoration',array(),array('version'=>GCU_VERSION,'schema'=>GCU_SCHEMA_VERSION,'future_schema'=>GCU_FUTURE_SCHEMA_VERSION));if(false===$audit){wp_die(esc_html__('Rollback completed but its mandatory audit record failed; File 14 remains contained in safe mode.','global-clinic-usp-integration'));}}$this->redirect(is_wp_error($x)?'rollback-unavailable':'snapshot-restored');}
public function toggle(){$this->authorize('gcu_toggle',GCU_Capabilities::SYSTEM_CHECK);$enabled=isset($_POST['enabled'])&&'1'===sanitize_key(wp_unslash($_POST['enabled']));if($enabled){$schema=GCU_Install::verify_schema();$future=GCU_Future_Intelligence::ensure_schema(true);$current=GCU_VERSION===(string)get_option(GCU_Install::VERSION_OPTION,'')&&GCU_SCHEMA_VERSION===(int)get_option(GCU_Install::SCHEMA_OPTION,0)&&GCU_FUTURE_SCHEMA_VERSION===(int)get_option(GCU_Future_Intelligence::SCHEMA_OPTION,0);if(is_wp_error($schema)||is_wp_error($future)||!$current){wp_die(esc_html__('Safe mode cannot be left until the current File 14 base and Future schemas are verified.','global-clinic-usp-integration'));}}update_option('gcu_enabled',$enabled?1:0,false);$audit=GCU_Plugin::instance()->repository()->audit('safe_mode_changed','module','file14','operations','',array(),array('enabled'=>$enabled));if(false===$audit||($enabled&&!get_option('gcu_enabled',0))){wp_die(esc_html__('The safe-mode change could not be confirmed by the mandatory audit trail. File 14 remains contained.','global-clinic-usp-integration'));}$this->redirect($enabled?'module-enabled':'safe-mode-enabled');}
public function migration_notice(){if(!GCU_Capabilities::can(GCU_Capabilities::SYSTEM_CHECK,null,'migration_notice')){return;}$l=get_option(GCU_Install::MIGRATION_LOG,array());if(empty($l['detected'])||get_user_meta(get_current_user_id(),'gcu_legacy_notice_seen',true)){return;}update_user_meta(get_current_user_id(),'gcu_legacy_notice_seen',1);echo'<div class="notice notice-warning is-dismissible"><p>'.esc_html__('File 14 detected the legacy SGC package. It performed a read-only inventory and did not overwrite or delete legacy pages, options or companion records.','global-clinic-usp-integration').'</p></div>';}
private function action_form($action,$label,array$fields=array()){?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="<?php echo esc_attr($action);?>"><?php foreach($fields as$n=>$v):?><input type="hidden" name="<?php echo esc_attr($n);?>" value="<?php echo esc_attr($v);?>"><?php endforeach;wp_nonce_field($action);submit_button($label,'secondary','submit',false);?></form><?php }
private function authorize($action,$cap){check_admin_referer($action);if(!GCU_Capabilities::can($cap,null,$action)){wp_die(esc_html__('You are not authorized to perform this action.','global-clinic-usp-integration'));}}
private function redirect($n){wp_safe_redirect(add_query_arg('gcu_notice',sanitize_key($n),admin_url('options-general.php?page=global-clinic-usp-integration')));exit;}
}
